  <button id="btnPrev">◀ Prev</button>
  <button id="btnNext">Next ▶</button>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
 (a) carbon         → SphereGeometry(0.30)  MeshPhong #4a4a50
 (a) hydrogen       → SphereGeometry(0.20)  MeshPhong #e6e4d8
 (a) C–C / C–H rod  → CylinderGeometry(r=0.07) MeshPhong #b9c6d6
 (b) ring bond      → flat PlaneGeometry strip, w=0.035 black; bold front bonds w=0.095
 (b) C–H stub       → flat strip w=0.03 black
 (b) numerals 1–6   → addLabel magenta #e6007e
 (b) H letters      → addLabel magenta / green / blue / black
 (b) eye icon       → ShapeGeometry almond (white) + gray blob + black outline Line + iris CircleGeometry
 (b) sightline      → magenta dash strips + ShapeGeometry arrowhead
 (b) 'Observer'     → addLabel black
 (c) Newman circle  → RingGeometry(0.87,0.91) black
 (c) front bonds    → flat strips w=0.055 from centre dot (CircleGeometry 0.075) to rim
 (c) back bonds     → flat strips w=0.045 from rim outward, staggered 60°
 (c) CH2 connectors → flat strips + addLabel 'CH<sub>2</sub>'
 sel. highlight     → RingGeometry magenta, shown on chosen ring position
 tags (a)(b)(c)     → addLabel bold black
──────────────────────────────────────────────────────────────────────────── */

const CSSC = { mag:'#e6007e', grn:'#00a651', blu:'#0072bc', blk:'#111111' };
const HEXC = { mag:0xe6007e, grn:0x00a651, blu:0x0072bc, blk:0x111111, gray:0xd9d9d9 };

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.62));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.95);
keyLight.position.set(3.5, 5.5, 4.5); scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.28);
fillLight.position.set(-4, -2.5, -3); scene.add(fillLight);

/* ── panel plumbing ─────────────────────────────────────────────────────── */
const panels = { a: new THREE.Group(), b: new THREE.Group(), c: new THREE.Group() };
const pmats  = { a: [], b: [], c: [] };
const LBL = [];
const HITS = [];
let curPanel = 'a', targetPanel = 'a', fade = 0, fadingOut = false;
let sel = null;

function mat(key, params, Type) {
  const m = new (Type || THREE.MeshBasicMaterial)(Object.assign({ transparent: true }, params));
  pmats[key].push(m);
  return m;
}

function flatLine(g, key, p0, p1, w, color, cap) {
  const dx = p1[0] - p0[0], dy = p1[1] - p0[1], len = Math.hypot(dx, dy);
  if (len < 1e-6) return null;
  const m = mat(key, { color, side: THREE.DoubleSide, depthWrite: false });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(len, w), m);
  mesh.position.set((p0[0] + p1[0]) / 2, (p0[1] + p1[1]) / 2, 0);
  mesh.rotation.z = Math.atan2(dy, dx);
  g.add(mesh);
  if (cap) {
    [p0, p1].forEach(p => {
      const c = new THREE.Mesh(new THREE.CircleGeometry(w / 2, 12), m);
      c.position.set(p[0], p[1], 0); g.add(c);
    });
  }
  return mesh;
}

function dashLine(g, key, p0, p1, w, color, dash, gap) {
  const dx = p1[0] - p0[0], dy = p1[1] - p0[1], len = Math.hypot(dx, dy);
  const ux = dx / len, uy = dy / len;
  let t = 0;
  while (t < len) {
    const t2 = Math.min(len, t + dash);
    flatLine(g, key, [p0[0] + ux * t, p0[1] + uy * t], [p0[0] + ux * t2, p0[1] + uy * t2], w, color);
    t = t2 + gap;
  }
}

function ringMesh(g, key, cx, cy, r, t, color) {
  const m = new THREE.Mesh(new THREE.RingGeometry(r - t / 2, r + t / 2, 72),
    mat(key, { color, side: THREE.DoubleSide, depthWrite: false }));
  m.position.set(cx, cy, 0); g.add(m); return m;
}

function dot(g, key, cx, cy, r, color) {
  const m = new THREE.Mesh(new THREE.CircleGeometry(r, 24),
    mat(key, { color, side: THREE.DoubleSide, depthWrite: false }));
  m.position.set(cx, cy, 0.002); g.add(m); return m;
}

function L(key, text, x, y, z, opts) {
  const o = opts || {};
  const e = addLabel(text, new THREE.Vector3(x, y, z || 0), o);
  e.panel = key; e.own = o.own || null; e.always = !!o.always;
  e.div.style.opacity = '0';
  LBL.push(e); return e;
}

function hitTarget(g, key, pos, r, info) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, 12, 8),
    new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }));
  m.position.copy(pos); g.add(m);
  registerInteractive(m, info);
  HITS.push({ obj: m, panel: key });
  return m;
}

/* ══════════════ PANEL (a) — ball & stick chair ═════════════════════════ */
const gA = panels.a;
const R = 1.25, PUCK = 0.25, CHL = 0.6;
const cPos = [];
for (let k = 1; k <= 6; k++) {
  const a = THREE.MathUtils.degToRad(60 * k);
  const y = (k % 2 === 1 ? 1 : -1) * PUCK;
  cPos.push(new THREE.Vector3(R * Math.cos(a), y, R * Math.sin(a)));
}
const carbonMat = mat('a', { color: 0x4a4a50, shininess: 55, specular: 0x9aa0a8 }, THREE.MeshPhongMaterial);
const hydroMat  = mat('a', { color: 0xe6e4d8, shininess: 45, specular: 0xffffff }, THREE.MeshPhongMaterial);
const bondMat   = mat('a', { color: 0xb9c6d6, shininess: 60, specular: 0xdfe8f2 }, THREE.MeshPhongMaterial);

function rod(g, a, b, r, m) {
  const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length();
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 18), m);
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  g.add(mesh); return mesh;
}

for (let i = 0; i < 6; i++) rod(gA, cPos[i], cPos[(i + 1) % 6], 0.07, bondMat);

for (let i = 0; i < 6; i++) {
  const k = i + 1;
  const s = (k % 2 === 1) ? 1 : -1;
  const C = cPos[i];
  const radial = new THREE.Vector3(C.x, 0, C.z).normalize();
  const axial = new THREE.Vector3(0, s, 0);
  const equat = radial.clone().add(new THREE.Vector3(0, -0.45 * s, 0)).normalize();
  [axial, equat].forEach(dirv => {
    const H = C.clone().addScaledVector(dirv, CHL);
    rod(gA, C, H, 0.055, bondMat);
    const hs = new THREE.Mesh(new THREE.SphereGeometry(0.20, 26, 20), hydroMat);
    hs.position.copy(H); gA.add(hs);
  });
  const cs = new THREE.Mesh(new THREE.SphereGeometry(0.30, 30, 24), carbonMat);
  cs.position.copy(C); gA.add(cs);
  registerInteractive(cs, {
    title: 'Ring carbon ' + k,
    tooltip: 'Carbon ' + k + ' — axial + equatorial H',
    body: 'Carbon ' + k + ' of the chair. Its axial C–H points straight ' + (s > 0 ? 'up' : 'down') +
          ' along the ring axis; its equatorial C–H splays outward around the ring rim. Bond angles stay near 109.5°.'
  });
  HITS.push({ obj: cs, panel: 'a' });
}
L('a', '<b>(a)</b>', -1.9, 1.85, 0, { fontSize: '16px', always: true });

/* ══════════════ PANEL (b) — line structure + observer ══════════════════ */
const gB = panels.b;
const S = 1.35;
