function syncLabelOpacity() {
  for (const e of LBL) {
    let o = (e.panel === curPanel) ? fade : 0;
    if (o > 0 && sel && !e.always && e.own !== sel) o *= 0.35;
    e.div.style.opacity = String(o);
  }
}
function syncMatOpacity() {
  pmats[curPanel].forEach(m => { m.opacity = fade; });
}

function applyPanel(k) {
  Object.keys(panels).forEach(key => {
    const g = panels[key];
    if (key === k) { if (!g.parent) scene.add(g); }
    else if (g.parent) scene.remove(g);
  });
  HITS.forEach(h => h.obj.layers.set(h.panel === k ? 0 : 1));
  pmats[k].forEach(m => { m.opacity = 0; });
  fade = 0;
  if (k === 'a') {
    setCameraView({ projection: 'perspective', azimuthDeg: 45, elevationDeg: 20, rollDeg: 0, heightFraction: 0.6 });
  } else {
    setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 0, rollDeg: 0,
      heightFraction: k === 'b' ? 0.70 : 0.66 });
  }
  controls.enableRotate = (k === 'a');
  controls.enablePan = (k === 'a');
  const hint = document.getElementById('orbitHint');
  if (hint) hint.style.color = (k === 'a') ? '#1a6a2a' : '#555';
  syncHighlights(); syncLabelOpacity(); syncMatOpacity(); syncButtons();
}

function requestPanel(k) {
  if (k === targetPanel && !fadingOut) { syncButtons(); return; }
  targetPanel = k;
  if (k === curPanel) { fadingOut = false; syncButtons(); return; }
  fadingOut = true;
  syncButtons();
}

let _last = performance.now();
(function fadeTick() {
  requestAnimationFrame(fadeTick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _last) / 1000); _last = now;
  if (fadingOut) {
    fade -= dt * 4.5;
    if (fade <= 0) { fade = 0; fadingOut = false; curPanel = targetPanel; applyPanel(curPanel); }
  } else if (fade < 1) {
    fade = Math.min(1, fade + dt * 4.5);
  }
  syncMatOpacity(); syncLabelOpacity();
})();

