/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
 (a) carbon         → SphereGeometry(0.30)  MeshPhong #4a4a50
 (a) hydrogen       → SphereGeometry(0.20)  MeshPhong #e6e4d8
 (a) C–C / C–H rod  → CylinderGeometry(r=0.07) MeshPhong #b9c6d6
 (b) ring bond      → flat PlaneGeometry strip, w=0.035 black; bold front bonds w=0.095
 (b) C–H stub       → flat strip w=0.03 black
 (b) numerals 1–6   → addLabel magenta #e6007e
 (b) H letters      → addLabel magenta / green / blue / black
 (b) eye icon       → ShapeGeometry almond (white) + gray blob + black outline Line + iris CircleGeometry
 (b) sightline      → magenta dash strips + ShapeGeometry arrowhead
 (b) 'Observer'     → addLabel black
 (c) Newman circle  → RingGeometry(0.87,0.91) black
 (c) front bonds    → flat strips w=0.055 from centre dot (CircleGeometry 0.075) to rim
 (c) back bonds     → flat strips w=0.045 from rim outward, staggered 60°
 (c) CH2 connectors → flat strips + addLabel 'CH<sub>2</sub>'
 sel. highlight     → RingGeometry magenta, shown on chosen ring position
 tags (a)(b)(c)     → addLabel bold black
──────────────────────────────────────────────────────────────────────────── */

const CSSC = { mag:'#e6007e', grn:'#00a651', blu:'#0072bc', blk:'#111111' };
const HEXC = { mag:0xe6007e, grn:0x00a651, blu:0x0072bc, blk:0x111111, gray:0xd9d9d9 };

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.62));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.95);
keyLight.position.set(3.5, 5.5, 4.5); scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.28);
