  const radial = new THREE.Vector3(C.x, 0, C.z).normalize();
  const axial = new THREE.Vector3(0, s, 0);
  const equat = radial.clone().add(new THREE.Vector3(0, -0.45 * s, 0)).normalize();
  [axial, equat].forEach(dirv => {
    const H = C.clone().addScaledVector(dirv, CHL);
    rod(gA, C, H, 0.055, bondMat);
    const hs = new THREE.Mesh(new THREE.SphereGeometry(0.20, 26, 20), hydroMat);
    hs.position.copy(H); gA.add(hs);
  });
  const cs = new THREE.Mesh(new THREE.SphereGeometry(0.30, 30, 24), carbonMat);
  cs.position.copy(C); gA.add(cs);
  registerInteractive(cs, {
    title: 'Ring carbon ' + k,
    tooltip: 'Carbon ' + k + ' — axial + equatorial H',
    body: 'Carbon ' + k + ' of the chair. Its axial C–H points straight ' + (s > 0 ? 'up' : 'down') +
          ' along the ring axis; its equatorial C–H splays outward around the ring rim. Bond angles stay near 109.5°.'
  });
  HITS.push({ obj: cs, panel: 'a' });
}
