/* ══════════════ panel switching / fading ═══════════════════════════════ */
function syncHighlights() {
  hlB1.visible = (sel === 1); hlB5.visible = (sel === 5);
  hlC1.visible = (sel === 1); hlC5.visible = (sel === 5);
}
function syncLabelOpacity() {
  for (const e of LBL) {
    let o = (e.panel === curPanel) ? fade : 0;
    if (o > 0 && sel && !e.always && e.own !== sel) o *= 0.35;
    e.div.style.opacity = String(o);
  }
}
function syncMatOpacity() {
  pmats[curPanel].forEach(m => { m.opacity = fade; });
}

function applyPanel(k) {
  Object.keys(panels).forEach(key => {
    const g = panels[key];
    if (key === k) { if (!g.parent) scene.add(g); }
    else if (g.parent) scene.remove(g);
  });
  HITS.forEach(h => h.obj.layers.set(h.panel === k ? 0 : 1));
  pmats[k].forEach(m => { m.opacity = 0; });
  fade = 0;
  if (k === 'a') {
    setCameraView({ projection: 'perspective', azimuthDeg: 45, elevationDeg: 20, rollDeg: 0, heightFraction: 0.6 });
  } else {
    setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 0, rollDeg: 0,
      heightFraction: k === 'b' ? 0.70 : 0.66 });
  }
  controls.enableRotate = (k === 'a');
  controls.enablePan = (k === 'a');
  const hint = document.getElementById('orbitHint');
  if (hint) hint.style.color = (k === 'a') ? '#1a6a2a' : '#555';
  syncHighlights(); syncLabelOpacity(); syncMatOpacity(); syncButtons();
}

function requestPanel(k) {
  if (k === targetPanel && !fadingOut) { syncButtons(); return; }
  targetPanel = k;
  if (k === curPanel) { fadingOut = false; syncButtons(); return; }
  fadingOut = true;
  syncButtons();
}

let _last = performance.now();
(function fadeTick() {
  requestAnimationFrame(fadeTick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _last) / 1000); _last = now;
  if (fadingOut) {
    fade -= dt * 4.5;
    if (fade <= 0) { fade = 0; fadingOut = false; curPanel = targetPanel; applyPanel(curPanel); }
  } else if (fade < 1) {
    fade = Math.min(1, fade + dt * 4.5);
  }
  syncMatOpacity(); syncLabelOpacity();
})();

/* ══════════════ selection ══════════════════════════════════════════════ */
function setSelection(p) {
  sel = (sel === p) ? null : p;
  syncHighlights(); syncLabelOpacity(); syncButtons();
}

/* ══════════════ UI wiring ══════════════════════════════════════════════ */
const bA = document.getElementById('btnPanelA');
const bB = document.getElementById('btnPanelB');
const bC = document.getElementById('btnPanelC');
const s1 = document.getElementById('btnSel1');
const s5 = document.getElementById('btnSel5');
const sN = document.getElementById('btnSelNone');

function syncButtons() {
  bA.classList.toggle('active', targetPanel === 'a');
  bB.classList.toggle('active', targetPanel === 'b');
  bC.classList.toggle('active', targetPanel === 'c');
  s1.classList.toggle('active', sel === 1);
  s5.classList.toggle('active', sel === 5);
  sN.classList.toggle('active', sel === null);
}

bA.onclick = () => { requestPanel('a'); setStep(0, true); };
bB.onclick = () => { requestPanel('b'); setStep(1, true); };
bC.onclick = () => { requestPanel('c'); setStep(2, true); };
s1.onclick = () => setSelection(1);
s5.onclick = () => setSelection(5);
sN.onclick = () => { sel = null; syncHighlights(); syncLabelOpacity(); syncButtons(); };

/* ══════════════ guided demo ════════════════════════════════════════════ */
const STEPS = [
  { title: '1. The 3D chair', panel: 'a',
    text: 'Start with the ball-and-stick model: six carbons pucker into a chair, each carrying one axial and one equatorial hydrogen. Drag to rotate and confirm the ring is not planar.' },
  { title: '2. Where the observer stands', panel: 'b',
    text: 'The same ring as a line structure, numbered 1–6. Two eyes sight down the ring at carbon 1 and carbon 5 — those two sightlines are what the Newman projections capture.' },
  { title: '3. The end-on view', panel: 'c',
    text: 'Looking down C1 and C5, every front C–H bond sits exactly between two back bonds: all neighbouring C–H bonds are staggered, so the chair carries no torsional strain. Click carbon 1 or 5 to trace a position back to the line drawing.' }
];
let stepIdx = 0;
function setStep(i, panelAlreadySet) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  const s = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepText').textContent = s.text;
  if (!panelAlreadySet) requestPanel(s.panel);
}
function goToStep(i) { setStep(i); }
document.getElementById('btnPrev').onclick = () => setStep(stepIdx - 1);
document.getElementById('btnNext').onclick = () => setStep(stepIdx + 1);

/* ══════════════ boot ═══════════════════════════════════════════════════ */
applyPanel('a');
setStep(0, true);
syncButtons();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

