/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
 (a) carbon          → SphereGeometry(0.28)  MeshPhong mid-gray #84898e
 (a) hydrogen        → SphereGeometry(0.185) MeshPhong off-white #efece0
 (a) C–C / C–H rod   → CylinderGeometry(r=0.068 / 0.052) MeshPhong #b9c6d6
                       C–H length 0.74 → open textbook ball-and-stick spacing
 (a) sel. halo       → SphereGeometry(0.42) magenta, transparent
 (b) ring bond       → flat PlaneGeometry strip w=0.035 black (bold front w=0.10)
                       vertices = TRUE parallel projection of the 3D chair
                       (azimuth 30°, elevation 20°) → genuine chair zig-zag
 (b) C–H stub        → flat strip w=0.032 black, from projected C to projected H
 (b) numerals 1–6    → addLabel magenta #e6007e bold 15px
 (b) H letters       → addLabel 14px bold: magenta ax on C2/C4/C5,
                       blue ax on C1, green eq on C1 & C4, black elsewhere
 (b) eye icon        → ShapeGeometry almond (white) + gray lid blob + outline + iris
 (b) sightline       → magenta dashed strips + ShapeGeometry arrowhead
 (c) Newman circle   → RingGeometry(0.88,0.92) black
 (c) front bonds     → thick strips centre→rim, back bonds rim→rim+0.30 (staggered 60°)
 (c) CH2 connectors  → bonds extended to x=±0.42 + addLabel 'CH<sub>2</sub>'
 composite view      → all three groups scaled/translated side by side,
                       panel (a) pre-rotated so it still reads as the 3D model
 panel tags (a)(b)(c)→ addLabel bold black 16px
──────────────────────────────────────────────────────────────────────────── */

const CSSC = { mag:'#e6007e', grn:'#00a651', blu:'#0072bc', blk:'#111111' };
const HEXC = { mag:0xe6007e, grn:0x00a651, blu:0x0072bc, blk:0x111111, gray:0xd9d9d9, wht:0xffffff };

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.78));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.85);
keyLight.position.set(3.5, 5.5, 4.5); scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.32);
fillLight.position.set(-4, -2.5, -3); scene.add(fillLight);

/* ── plumbing ───────────────────────────────────────────────────────────── */
const panels = { a: new THREE.Group(), b: new THREE.Group(), c: new THREE.Group() };
const pmats  = { a: [], b: [], c: [] };
const LBL = [];
const HITS = [];
const ACTIVE = { a:['a'], b:['b'], c:['c'], all:['a','b','c'] };
let curPanel = 'a', targetPanel = 'a', fade = 0, fadingOut = false;
let sel = null;

const matCache = new Map();
function matFor(key, color) {
  const id = key + '|' + color;
  if (matCache.has(id)) return matCache.get(id);
  const m = new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide,
    transparent: true, depthWrite: false, opacity: 0 });
  matCache.set(id, m); pmats[key].push(m); return m;
}
function phong(key, params) {
  const m = new THREE.MeshPhongMaterial(Object.assign({ transparent: true, opacity: 0 }, params));
  pmats[key].push(m); return m;
}

function flatLine(g, key, p0, p1, w, color, cap, z) {
  const dx = p1[0] - p0[0], dy = p1[1] - p0[1], len = Math.hypot(dx, dy);
  if (len < 1e-6) return null;
  const m = matFor(key, color);
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(len, w), m);
  mesh.position.set((p0[0] + p1[0]) / 2, (p0[1] + p1[1]) / 2, z || 0);
  mesh.rotation.z = Math.atan2(dy, dx);
  g.add(mesh);
  if (cap) [p0, p1].forEach(p => {
    const c = new THREE.Mesh(new THREE.CircleGeometry(w / 2, 12), m);
    c.position.set(p[0], p[1], z || 0); g.add(c);
  });
  return mesh;
}
function dashLine(g, key, p0, p1, w, color, dash, gap, z) {
  const dx = p1[0] - p0[0], dy = p1[1] - p0[1], len = Math.hypot(dx, dy);
  const ux = dx / len, uy = dy / len;
  let t = 0;
  while (t < len) {
    const t2 = Math.min(len, t + dash);
    flatLine(g, key, [p0[0] + ux * t, p0[1] + uy * t], [p0[0] + ux * t2, p0[1] + uy * t2], w, color, false, z);
    t = t2 + gap;
  }
}
function ringMesh(g, key, cx, cy, r, t, color, z) {
  const m = new THREE.Mesh(new THREE.RingGeometry(r - t / 2, r + t / 2, 80), matFor(key, color));
  m.position.set(cx, cy, z || 0); g.add(m); return m;
}
function dot(g, key, cx, cy, r, color, z) {
  const m = new THREE.Mesh(new THREE.CircleGeometry(r, 28), matFor(key, color));
  m.position.set(cx, cy, z || 0); g.add(m); return m;
}
function L(key, text, x, y, opts) {
  const o = opts || {};
  const px = o.px || 14;
  const e = addLabel(text, new THREE.Vector3(x, y, o.z || 0),
    { color: o.color, fontSize: px + 'px', bold: !!o.bold });
  e.local = new THREE.Vector3(x, y, o.z || 0);
  e.panel = key; e.own = o.own || null; e.always = !!o.always; e.px = px; e.fixed = !!o.fixed;
  e.div.style.opacity = '0';
  LBL.push(e); return e;
}
function hitTarget(g, key, x, y, z, r, info) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, 12, 8),
    new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }));
  m.position.set(x, y, z); g.add(m);
  registerInteractive(m, info);
  HITS.push({ obj: m, panel: key });
  return m;
}

/* ── shared chair geometry (bond ≈1, radius 1.25, pucker ±0.25) ─────────── */
function P3(k) {
  const a = THREE.MathUtils.degToRad(60 * k);
  return new THREE.Vector3(1.25 * Math.cos(a), (k % 2 === 1 ? 0.25 : -0.25), 1.25 * Math.sin(a));
}
function hDirs(k) {
  const s = (k % 2 === 1) ? 1 : -1;
  const P = P3(k);
  const radial = new THREE.Vector3(P.x, 0, P.z).normalize();
  return {
    ax: new THREE.Vector3(0, s, 0),
    eq: radial.clone().add(new THREE.Vector3(0, -0.45 * s, 0)).normalize(),
    up: s > 0
  };
}
// display numbering 1..6 → 3D index k (1 lower-right … 6 upper-right in panel b)
const kOf = i => ((i + 4) % 6) + 1;

/* ══════════════ PANEL (a) — ball & stick chair ═════════════════════════ */
const gA = panels.a;
const carbonMat = phong('a', { color: 0x84898e, shininess: 34, specular: 0xbcc2c8 });
const hydroMat  = phong('a', { color: 0xefece0, shininess: 30, specular: 0xffffff });
const bondMat   = phong('a', { color: 0xb9c6d6, shininess: 45, specular: 0xdfe8f2 });
function rod(g, a, b, r, m) {
  const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length();
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 18), m);
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  g.add(mesh); return mesh;
}
const CH_LEN = 0.74;
const aPos = [];
for (let i = 1; i <= 6; i++) aPos.push(P3(kOf(i)));
for (let i = 0; i < 6; i++) rod(gA, aPos[i], aPos[(i + 1) % 6], 0.068, bondMat);
const haloMat = new THREE.MeshBasicMaterial({ color: HEXC.mag, transparent: true, opacity: 0, depthWrite: false });
const haloA = {};
for (let i = 1; i <= 6; i++) {
  const k = kOf(i), C = aPos[i - 1], d = hDirs(k);
  [d.ax, d.eq].forEach(dirv => {
    const H = C.clone().addScaledVector(dirv, CH_LEN);
    rod(gA, C, H, 0.052, bondMat);
    const hs = new THREE.Mesh(new THREE.SphereGeometry(0.185, 26, 20), hydroMat);
    hs.position.copy(H); gA.add(hs);
  });
  const cs = new THREE.Mesh(new THREE.SphereGeometry(0.28, 30, 24), carbonMat);
  cs.position.copy(C); gA.add(cs);
  registerInteractive(cs, {
    title: 'Ring carbon ' + i,
    tooltip: 'Carbon ' + i + ' — axial + equatorial H',
    body: 'Carbon ' + i + ' of the chair. Its axial C–H points straight ' + (d.up ? 'up' : 'down') +
          ' along the ring axis; its equatorial C–H splays outward around the rim. All bond angles stay near 109.5°, so the chair is strain-free.',
    onClick: () => { if (i === 1 || i === 5) setSelection(i); }
  });
  HITS.push({ obj: cs, panel: 'a' });
  if (i === 1 || i === 5) {
    const h = new THREE.Mesh(new THREE.SphereGeometry(0.42, 20, 16), haloMat);
    h.position.copy(C); h.visible = false; gA.add(h); haloA[i] = h;
  }
}

/* ══════════════ PANEL (b) — line structure + observer ══════════════════ */
const gB = panels.b;
const AZ = THREE.MathUtils.degToRad(30), EL = THREE.MathUtils.degToRad(20), SB = 1.35;
const _sa = Math.sin(AZ), _ca = Math.cos(AZ), _se = Math.sin(EL), _ce = Math.cos(EL);
function prj(P) {
  return [(P.x * _sa - P.z * _ca) * SB,
          (-P.x * _ca * _se + P.y * _ce - P.z * _sa * _se) * SB];
}
const V = [];
for (let i = 1; i <= 6; i++) V.push(prj(P3(kOf(i))));

const THIN = 0.035, BOLD = 0.10;
for (let i = 0; i < 6; i++) {
  const bold = (i === 0 || i === 1);          // C1–C2 (nearest) and C2–C3
  flatLine(gB, 'b', V[i], V[(i + 1) % 6], bold ? BOLD : THIN, HEXC.blk, true, bold ? 0.02 : 0.0);
}

// Source colour key: magenta axial H on C2, C4, C5 · blue axial H on C1 ·
// green equatorial H at C1 and C4 · everything else black.
const HCOL = {
  1: { ax: 'blu', eq: 'grn' }, 2: { ax: 'mag', eq: 'blk' }, 3: { ax: 'blk', eq: 'blk' },
  4: { ax: 'mag', eq: 'grn' }, 5: { ax: 'mag', eq: 'blk' }, 6: { ax: 'blk', eq: 'blk' }
};
const OWN_B = { 1: 1, 2: 1, 4: 5, 5: 5 };
for (let i = 1; i <= 6; i++) {
  const k = kOf(i), P = P3(k), d = hDirs(k);
  [['ax', d.ax], ['eq', d.eq]].forEach(([type, dir]) => {
    const pB = prj(P.clone().addScaledVector(dir, 0.60));
    const pL = prj(P.clone().addScaledVector(dir, 0.98));
    flatLine(gB, 'b', V[i - 1], pB, 0.032, HEXC.blk, true, 0.01);
    L('b', 'H', pL[0], pL[1], { color: CSSC[HCOL[i][type]], px: 14, bold: true, own: OWN_B[i] || null });
  });
}
const NUMOFF = { 1: [-0.24, 0.27], 2: [0.26, -0.23], 3: [0.30, 0.17],
                 4: [0.28, -0.25], 5: [-0.32, 0.11], 6: [-0.32, -0.15] };
for (let i = 1; i <= 6; i++) {
  const o = NUMOFF[i];
  L('b', String(i), V[i - 1][0] + o[0], V[i - 1][1] + o[1],
    { color: CSSC.mag, px: 16, bold: true, own: OWN_B[i] || null });
}

/* eyes */
function eyeIcon(g, cx, cy) {
  const blob = new THREE.Shape();
  blob.moveTo(-0.56, -0.03);
  blob.quadraticCurveTo(-0.12, 0.62, 0.54, 0.16);
  blob.quadraticCurveTo(0.30, -0.54, -0.56, -0.03);
  const bm = new THREE.Mesh(new THREE.ShapeGeometry(blob), matFor('b', HEXC.gray));
  bm.position.set(cx, cy, -0.02); g.add(bm);

  const sh = new THREE.Shape();
  sh.moveTo(-0.37, 0); sh.quadraticCurveTo(0, 0.29, 0.37, 0);
  sh.quadraticCurveTo(0, -0.29, -0.37, 0);
  const wm = new THREE.Mesh(new THREE.ShapeGeometry(sh), matFor('b', HEXC.wht));
  wm.position.set(cx, cy, 0.0); g.add(wm);
  const pts = sh.getPoints(56);
  for (let i = 0; i < pts.length - 1; i++)
    flatLine(g, 'b', [cx + pts[i].x, cy + pts[i].y], [cx + pts[i + 1].x, cy + pts[i + 1].y],
      0.028, HEXC.blk, false, 0.012);
  dot(g, 'b', cx - 0.05, cy, 0.108, HEXC.blk, 0.02);
  dot(g, 'b', cx - 0.09, cy + 0.045, 0.033, HEXC.wht, 0.03);
}
const EYE_U = [4.05, 0.50], EYE_L = [4.62, -0.48];
eyeIcon(gB, EYE_U[0], EYE_U[1]);
eyeIcon(gB, EYE_L[0], EYE_L[1]);
L('b', 'Observer', 4.35, -1.35, { px: 15, always: true });

function sightline(from, to) {
  const dx = to[0] - from[0], dy = to[1] - from[1], l = Math.hypot(dx, dy);
  const ux = dx / l, uy = dy / l;
  const p0 = [from[0] + ux * 0.55, from[1] + uy * 0.55];
  const p1 = [from[0] + ux * (l - 0.32), from[1] + uy * (l - 0.32)];
  dashLine(gB, 'b', p0, p1, 0.035, HEXC.mag, 0.18, 0.13, 0.03);
  const shape = new THREE.Shape();
  shape.moveTo(0, 0); shape.lineTo(-0.21, 0.095); shape.lineTo(-0.21, -0.095); shape.closePath();
  const head = new THREE.Mesh(new THREE.ShapeGeometry(shape), matFor('b', HEXC.mag));
  head.position.set(p1[0], p1[1], 0.03);
  head.rotation.z = Math.atan2(uy, ux);
  gB.add(head);
}
sightline(EYE_U, V[4]);   // upper eye → carbon 5
sightline(EYE_L, V[0]);   // lower eye → carbon 1

const hlB1 = ringMesh(gB, 'b', V[0][0], V[0][1], 0.22, 0.06, HEXC.mag, 0.04);
const hlB5 = ringMesh(gB, 'b', V[4][0], V[4][1], 0.22, 0.06, HEXC.mag, 0.04);
hlB1.visible = hlB5.visible = false;

hitTarget(gB, 'b', V[0][0], V[0][1], 0, 0.32, {
  title: 'Carbon 1 — front atom of the left Newman circle',
  tooltip: 'Click: track ring position 1',
  body: 'The lower observer sights along C1→C2. In that end-on view C1 becomes the front carbon (the dot) of the LEFT Newman circle: its green equatorial H and blue axial H keep the same colours there.',
  onClick: () => setSelection(1)
});
hitTarget(gB, 'b', V[4][0], V[4][1], 0, 0.32, {
  title: 'Carbon 5 — front atom of the right Newman circle',
  tooltip: 'Click: track ring position 5',
  body: 'The upper observer sights along C5→C4. C5 becomes the front carbon of the RIGHT Newman circle; C4 is the back atom hidden directly behind it, its axial H drawn magenta.',
  onClick: () => setSelection(5)
});
hitTarget(gB, 'b', EYE_U[0], EYE_U[1], 0, 0.45, {
  title: 'Observer — sighting down C5→C4',
  tooltip: 'Upper eye: looks along C5→C4',
  body: 'Placing the eye on the C5–C4 axis collapses that bond to a point: the front carbon becomes a dot and the back carbon a circle. That is exactly the right-hand Newman projection in panel (c).'
});
hitTarget(gB, 'b', EYE_L[0], EYE_L[1], 0, 0.45, {
  title: 'Observer — sighting down C1→C2',
  tooltip: 'Lower eye: looks along C1→C2',
  body: 'The second sightline runs along C1–C2 and produces the left-hand Newman projection in panel (c). Both views show perfectly staggered bonds.'
});

/* ══════════════ PANEL (c) — Newman projections ═════════════════════════ */
const gC = panels.c;
const CR = 0.90, CX = [-1.6, 1.6], LINK_X = 0.42, LINK_Y = 0.681;
function polar(cx, r, ang) {
  const a = THREE.MathUtils.degToRad(ang);
  return [cx + r * Math.cos(a), r * Math.sin(a)];
}
function newman(cx, spec, own, centreNum, numPos) {
  ringMesh(gC, 'c', cx, 0, CR, 0.042, HEXC.blk, 0.0);
  spec.front.forEach(b => {
    flatLine(gC, 'c', [cx, 0], polar(cx, CR, b.ang), 0.055, HEXC.blk, true, 0.01);
    if (b.link) flatLine(gC, 'c', polar(cx, CR, b.ang), b.link, 0.055, HEXC.blk, true, 0.01);
    if (b.h) {
      const p = polar(cx, CR + 0.26, b.ang);
      L('c', 'H', p[0], p[1], { color: CSSC[b.h], px: 14, bold: true, own });
    }
  });
  spec.back.forEach(b => {
    const end = b.link || polar(cx, CR + 0.30, b.ang);
    flatLine(gC, 'c', polar(cx, CR, b.ang), end, 0.045, HEXC.blk, true, 0.008);
    if (b.h) {
      const p = polar(cx, CR + 0.58, b.ang);
      L('c', 'H', p[0], p[1], { color: CSSC[b.h], px: 14, bold: true, own });
    }
  });
  dot(gC, 'c', cx, 0, 0.078, HEXC.blk, 0.03);
  L('c', centreNum, cx + numPos[0], numPos[1], { color: CSSC.mag, px: 16, bold: true, own });
}
// LEFT: front = C1 (green eq H @150, blue ax H @270, bond to C6 @30)
//       back  = C2 (magenta ax H @90, green eq H @210, bond to C3 @330)
newman(CX[0], {
  front: [{ ang: 150, h: 'grn' }, { ang: 270, h: 'blu' }, { ang: 30, link: [-LINK_X, LINK_Y] }],
  back:  [{ ang: 90, h: 'mag' }, { ang: 210, h: 'grn' }, { ang: 330, link: [-LINK_X, -LINK_Y] }]
}, 1, '1', [0.02, -0.30]);
// RIGHT: front = C5 (black eq H @30, blue ax H @270, bond to C6 @150)
//        back  = C4 (magenta ax H @90, black eq H @330, bond to C3 @210)
newman(CX[1], {
  front: [{ ang: 30, h: 'blk' }, { ang: 270, h: 'blu' }, { ang: 150, link: [LINK_X, LINK_Y] }],
  back:  [{ ang: 90, h: 'mag' }, { ang: 330, h: 'blk' }, { ang: 210, link: [LINK_X, -LINK_Y] }]
}, 5, '5', [0.02, -0.30]);

L('c', '2', -2.24, 1.16, { color: CSSC.mag, px: 16, bold: true, own: 1 });
L('c', '4',  2.24, 1.16, { color: CSSC.mag, px: 16, bold: true, own: 5 });
L('c', 'CH<sub>2</sub>', 0,  LINK_Y, { px: 15, always: true });
L('c', 'CH<sub>2</sub>', 0, -LINK_Y, { px: 15, always: true });
L('c', '6', -0.05,  1.06, { color: CSSC.mag, px: 16, bold: true, always: true });
L('c', '3', -0.05, -1.06, { color: CSSC.mag, px: 16, bold: true, always: true });

const hlC1 = ringMesh(gC, 'c', CX[0], 0, CR + 0.12, 0.055, HEXC.mag, 0.04);
const hlC5 = ringMesh(gC, 'c', CX[1], 0, CR + 0.12, 0.055, HEXC.mag, 0.04);
hlC1.visible = hlC5.visible = false;

hitTarget(gC, 'c', CX[0], 0, 0, 0.62, {
  title: 'Newman view down C1 → C2',
  tooltip: 'Click: track ring position 1',
  body: 'Front atom = C1 (the dot; heavy bonds to its green equatorial H, its blue axial H and up-right to CH₂ = C6). Back atom = C2 (bonds drawn to the rim: magenta axial H, green equatorial H, and down-right to CH₂ = C3). Every front bond bisects a pair of back bonds — perfectly staggered, no torsional strain.',
  onClick: () => setSelection(1)
});
hitTarget(gC, 'c', CX[1], 0, 0, 0.62, {
  title: 'Newman view down C5 → C4',
  tooltip: 'Click: track ring position 5',
  body: 'Front atom = C5, back atom = C4 (magenta axial H), again staggered by 60°. The two circles are joined by the CH₂ groups C6 (top) and C3 (bottom), which close the six-membered ring.',
  onClick: () => setSelection(5)
});

/* ── panel tags ─────────────────────────────────────────────────────────── */
const TAGS = {
  a: L('a', '<b>(a)</b>', 0, 0, { px: 16, always: true, fixed: true }),
  b: L('b', '<b>(b)</b>', 0, 0, { px: 16, always: true, fixed: true }),
  c: L('c', '<b>(c)</b>', 0, 0, { px: 16, always: true, fixed: true })
};
const _right = new THREE.Vector3(), _up = new THREE.Vector3();
function anchorTags() {
  if (curPanel === 'all') {
    TAGS.a.pos.set(-5.35, 1.55, 0);
    TAGS.b.pos.set(-1.95, 1.55, 0);
    TAGS.c.pos.set(3.35, 1.25, 0);
    return;
  }
  const e = TAGS[curPanel];
  if (!e || !camera.isPerspectiveCamera) return;
  const dist = camera.position.distanceTo(controls.target);
  const halfH = Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2) * dist;
  const halfW = halfH * camera.aspect;
  _right.setFromMatrixColumn(camera.matrixWorld, 0).normalize();
  _up.setFromMatrixColumn(camera.matrixWorld, 1).normalize();
  e.pos.copy(controls.target).addScaledVector(_right, -0.88 * halfW).addScaledVector(_up, 0.86 * halfH);
}

/* ══════════════ composite layout ═══════════════════════════════════════ */
// Rotate panel (a) so that a front-on composite camera still sees the
// authored 45°/20° ball-and-stick pose.
const _dummy = new THREE.Object3D();
{
  const az = THREE.MathUtils.degToRad(45), el = THREE.MathUtils.degToRad(20);
  _dummy.position.set(Math.cos(az) * Math.cos(el), Math.sin(el), Math.sin(az) * Math.cos(el));
  _dummy.up.set(0, 1, 0);
  _dummy.lookAt(0, 0, 0);
  _dummy.updateMatrixWorld(true);
}
const QA = _dummy.quaternion.clone().invert();

function applyLayout(k) {
  if (k === 'all') {
    panels.a.scale.setScalar(0.62); panels.a.quaternion.copy(QA); panels.a.position.set(-4.0, 0.05, 0);
    panels.b.scale.setScalar(0.58); panels.b.quaternion.identity(); panels.b.position.set(0.0, 0, 0);
    panels.c.scale.setScalar(0.58); panels.c.quaternion.identity(); panels.c.position.set(5.1, 0, 0);
  } else {
    panels.a.scale.setScalar(1); panels.a.quaternion.identity(); panels.a.position.set(0, 0, 0);
    panels.b.scale.setScalar(1); panels.b.quaternion.identity(); panels.b.position.set(0, 0, 0);
    panels.c.scale.setScalar(1); panels.c.quaternion.identity(); panels.c.position.set(0, 0, 0);
  }
  panels.a.updateMatrixWorld(true);
  panels.b.updateMatrixWorld(true);
